<?php require 'config/database.php';require 'includes/auth.php';require_role('admin');$users=$pdo->query("SELECT id,name,email,student_id,role,status,points_balance,created_at FROM users ORDER BY created_at DESC")->fetchAll();$pageTitle='User management';include 'includes/header.php';?><div class="page-heading"><span class="eyebrow">ADMINISTRATION</span><h1>User management</h1><p>Review registered student and staff accounts.</p></div><section class="panel table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Student ID</th><th>Role</th><th>Status</th><th>Points</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=htmlspecialchars($u['name'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['student_id']??'—')?></td><td><?=htmlspecialchars($u['role'])?></td><td><?=htmlspecialchars($u['status'])?></td><td><?=$u['points_balance']?></td></tr><?php endforeach;?></tbody></table></section><?php include 'includes/footer.php';?>
